INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Datenbankmanagementsystem dasselbe wie eine Datenbank?', 2, '[{"text": "Nein", "correct": true, "because": "DBMS verwaltet, Datenbank speichert"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Funktionen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem DBMS?', 3, '[{"text": "Daten effizient verwalten", "correct": true, "because": "Organisiert und sichert Daten"}, {"text": "Hardware optimieren", "correct": false, "because": "Kein Hardware-Fokus"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einem DBMS?', 5, '[{"text": "Abfragesprache", "correct": true, "because": "z. B. SQL für Zugriff"}, {"text": "Datenbankengine", "correct": true, "because": "Verarbeitet Daten"}, {"text": "Grafiktreiber", "correct": false, "because": "Kein DBMS-Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein DBMS unterstützt mehrere Nutzer. b) Es erstellt Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist keine DBMS-Aufgabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Wahl eines DBMS?', 4, '[{"text": "Skalierbarkeit", "correct": false, "because": "Wichtig für Wachstum"}, {"text": "Sicherheit", "correct": false, "because": "Schützt Daten"}, {"text": "Farbschema", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes DBMS relationale Datenbanken nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch NoSQL möglich"}, {"text": "Ja", "correct": false, "because": "Verschiedene Typen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches DBMS ist für relationale Datenbanken typisch?', 3, '[{"text": "MySQL", "correct": true, "because": "Weit verbreitet"}, {"text": "MongoDB", "correct": false, "because": "NoSQL-System"}, {"text": "Apache", "correct": false, "because": "Webserver"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein DBMS?', 5, '[{"text": "Datenintegrität", "correct": true, "because": "Sichert Konsistenz"}, {"text": "Mehrbenutzerzugriff", "correct": true, "because": "Gemeinsame Nutzung"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Hardware-Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein DBMS verwaltet Datenbanken. b) Es ist immer kostenlos. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein DBMS?', 4, '[{"text": "Abfragesprache", "correct": false, "because": "Für Zugriff nötig"}, {"text": "Speichermedium", "correct": false, "because": "Datenablage erforderlich"}, {"text": "3D-Drucker", "correct": true, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein DBMS immer Cloud-basiert?', 2, '[{"text": "Nein", "correct": true, "because": "Auch lokal möglich"}, {"text": "Ja", "correct": false, "because": "Flexibel einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben übernimmt ein DBMS?', 4, '[{"text": "Daten speichern", "correct": true, "because": "Kernfunktion"}, {"text": "Zugriffe kontrollieren", "correct": true, "because": "Sicherheitsfeature"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein DBMS keine Backups braucht. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Backups schützen Daten"}, {"text": "Ja", "correct": false, "because": "Sicherung essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Wahl eines DBMS?', 3, '[{"text": "Leistung", "correct": true, "because": "Schnelle Verarbeitung"}, {"text": "Schnelle Installation", "correct": false, "because": "Funktion wichtiger"}, {"text": "Minimale Kosten", "correct": false, "because": "Qualität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) DBMS unterstützt Transaktionen. b) Es ist nur für kleine Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Größen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Typen von DBMS gibt es?', 5, '[{"text": "Relational", "correct": true, "because": "Tabellenbasiert"}, {"text": "NoSQL", "correct": true, "because": "Flexibel für unstrukturierte Daten"}, {"text": "Grafikbasiert", "correct": false, "because": "Kein DBMS-Typ"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem DBMS unwichtig?', 3, '[{"text": "Sicherheitsfeatures", "correct": false, "because": "Schützt Daten"}, {"text": "Skalierbarkeit", "correct": false, "because": "Für Wachstum nötig"}, {"text": "Tastaturdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein DBMS ohne SQL auskommen?', 3, '[{"text": "Ja", "correct": true, "because": "NoSQL nutzt andere Sprachen"}, {"text": "Nein", "correct": false, "because": "SQL nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein DBMS nur für Firmen ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch privat nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Datenbankengine?', 4, '[{"text": "Verarbeitet Abfragen", "correct": true, "because": "Kern des DBMS"}, {"text": "Grafiken rendert", "correct": false, "because": "Kein Zusammenhang"}, {"text": "Netzwerk steuert", "correct": false, "because": "Anderer Fokus"}]');
